From a6d1cc8834981a605c6ae899dd4f77dfe96dab7f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:26:43 +0100
Subject: [PATCH] containments/desktop: make the Filter page's file type rule
 visible

The default "all/all" file types showed as unchecked and applying saved
an empty list, so the name pattern never matched. Show them as checked,
save every type checked as "all/all" and say when none is checked.

BUG: 502692
---
 .../package/contents/ui/ConfigFilter.qml      | 33 ++++++++++++-------
 .../desktop/plugins/folder/mimetypesmodel.cpp |  7 +++-
 2 files changed, 28 insertions(+), 12 deletions(-)

diff --git a/containments/desktop/package/contents/ui/ConfigFilter.qml b/containments/desktop/package/contents/ui/ConfigFilter.qml
index 37dddc5dc9..2d89275634 100644
--- a/containments/desktop/package/contents/ui/ConfigFilter.qml
+++ b/containments/desktop/package/contents/ui/ConfigFilter.qml
@@ -52,8 +52,18 @@ KCM.ScrollViewKCM {
                 types.push(index(i, 0).data(Qt.UserRole));
             }

-            mimeTypesModel.checkedTypes = mimeTypesModel.checkedTypes
-                .filter(x => types.indexOf(x) === -1);
+            var checked = [];
+
+            for (var row = 0; row < mimeTypesModel.rowCount(); ++row) {
+                var rowIndex = mimeTypesModel.index(row, 0);
+                var name = rowIndex.data(Qt.UserRole);
+
+                if (rowIndex.data(Qt.CheckStateRole) === Qt.Checked && types.indexOf(name) === -1) {
+                    checked.push(name);
+                }
+            }
+
+            mimeTypesModel.checkedTypes = checked;
         }
     }

@@ -77,6 +87,13 @@ KCM.ScrollViewKCM {
             enabled: (filterMode.currentIndex > 0)
         }

+        Kirigami.InlineMessage {
+            Layout.fillWidth: true
+            type: Kirigami.MessageType.Information
+            text: i18nc("@info", "The file name pattern only applies to files of the checked types.")
+            visible: filterMode.currentIndex > 0 && !mimeTypesModel.checkedTypes.some(type => type.length > 0)
+        }
+
         CheckBox {
             id: showHiddenFiles
             Kirigami.FormData.label: i18nc("@option:check prefix", "Show hidden files:")
@@ -128,6 +145,7 @@ KCM.ScrollViewKCM {
             required property string name
             required property string comment
             required property var decoration
+            required property var model

             contentItem: RowLayout {
                 Layout.fillWidth: true
@@ -138,15 +156,8 @@ KCM.ScrollViewKCM {
                     Layout.fillHeight: true
                     CheckBox {
                         Layout.fillHeight: true
-                        checked: mimeTypesModel.checkedTypes.indexOf(delegate.name) >= 0
-                        onToggled: {
-                            let idx = mimeTypesModel.checkedTypes.indexOf(delegate.name);
-                            if (idx >= 0) {
-                                mimeTypesModel.checkedTypes.splice(idx, 1);
-                            } else {
-                                mimeTypesModel.checkedTypes.push(delegate.name)
-                            }
-                        }
+                        checked: delegate.model.checked === Qt.Checked
+                        onToggled: delegate.model.checked = checked ? Qt.Checked : Qt.Unchecked
                     }
                     Kirigami.Icon {
                         Layout.fillHeight: true
diff --git a/containments/desktop/plugins/folder/mimetypesmodel.cpp b/containments/desktop/plugins/folder/mimetypesmodel.cpp
index b5da3968a2..3b9759b15f 100644
--- a/containments/desktop/plugins/folder/mimetypesmodel.cpp
+++ b/containments/desktop/plugins/folder/mimetypesmodel.cpp
@@ -97,6 +97,10 @@ int MimeTypesModel::indexOfType(const QString &name) const

 QStringList MimeTypesModel::checkedTypes() const
 {
+    if (!m_checkedRows.contains(false)) {
+        return QStringList(QStringLiteral("all/all"));
+    }
+
     QStringList list;

     for (int i = 0; i < m_checkedRows.size(); ++i) {
@@ -114,7 +118,8 @@ QStringList MimeTypesModel::checkedTypes() const

 void MimeTypesModel::setCheckedTypes(const QStringList &list)
 {
-    m_checkedRows = QList<bool>(m_mimeTypesList.size(), false);
+    const bool allTypes = list.contains(QLatin1String("all/all")) || list.contains(QLatin1String("all/allfiles"));
+    m_checkedRows = QList<bool>(m_mimeTypesList.size(), allTypes);

     for (const QString &name : list) {
         const int row = indexOfType(name);
-- 
